{"query":"SELECT p_lines, c_lines, shared_lines
FROM (
  SELECT count(DISTINCT cell_line) as p_lines FROM cell_line_analysis_data WHERE analysis_type = 'PROGENy'
), (
  SELECT count(DISTINCT cell_line) as c_lines FROM cell_line_analysis_data WHERE analysis_type = 'CytoSig'
), (
  SELECT count(DISTINCT p.cell_line) as shared_lines
  FROM (SELECT DISTINCT cell_line FROM cell_line_analysis_data WHERE analysis_type = 'PROGENy') p
  JOIN (SELECT DISTINCT cell_line FROM cell_line_analysis_data WHERE analysis_type = 'CytoSig') c
  ON p.cell_line = c.cell_line
)"}

